package lk.gov.health.govcare.draft;
import lk.gov.health.govcare.common.*;import lk.gov.health.govcare.security.*;import org.springframework.stereotype.Service;import java.util.*;import static lk.gov.health.govcare.draft.DraftDtos.*;
@Service public class DraftService { private final SqlSupport sql; private final JsonSupport json; private final ClinicalPatientAccess access; public DraftService(SqlSupport s,JsonSupport j,ClinicalPatientAccess access){sql=s;json=j;this.access=access;}
 public Map<String,Object> save(GovCarePrincipal a,SaveRequest q){if(q==null||q.workflowType()==null||q.formType()==null||q.data()==null)throw ApiException.badRequest("Draft workflow, form type, and data are required.");String status=q.status()==null?"IN_PROGRESS":q.status().toUpperCase(Locale.ROOT);if(!Set.of("DRAFT","IN_PROGRESS","SAVED").contains(status))throw ApiException.badRequest("Invalid draft status.");String patient=q.patientId();if(patient!=null&&!patient.isBlank()){UUID id=sql.uuid(patient,"patientId");a="CKD_AI_ASSESSMENT".equals(q.workflowType())?access.clinicalScope(a,id,true):access.scopeToPatient(a,id);}if(patient!=null&&!patient.isBlank())sql.required("select id from patients where id=cast(:patient as uuid) and hospital_id=:hospital and status<>'deleted'",Map.of("patient",patient,"hospital",a.hospitalId()),"Patient not found.");Map<String,Object> p=new HashMap<>();p.put("user",a.id());p.put("hospital",a.hospitalId());p.put("department",a.departmentId());p.put("patient",patient==null||patient.isBlank()?null:patient);p.put("workflow",q.workflowType());p.put("form",q.formType());p.put("data",json.write(q.data()));p.put("status",status);p.put("request",q.requestId());p.put("version",q.version()==null?0:q.version());if(q.draftId()!=null&&!q.draftId().isBlank()){int changed=sql.update("update workflow_drafts set draft_data=cast(:data as jsonb),status=:status,version=version+1,updated_at=now(),last_accessed_at=now(),request_id=:request where id=cast(:id as uuid) and user_id=:user and hospital_id=:hospital and version=:version and status in('DRAFT','IN_PROGRESS','SAVED')",Map.of("data",p.get("data"),"status",status,"request",q.requestId(),"id",q.draftId(),"user",a.id(),"hospital",a.hospitalId(),"version",p.get("version")));if(changed==0)throw ApiException.conflict("The draft was updated elsewhere. Reload it before saving.");return get(a,q.draftId());}Map<String,Object> row=sql.required("insert into workflow_drafts(user_id,hospital_id,department_id,patient_id,workflow_type,form_type,draft_data,status,request_id) values(:user,:hospital,:department,cast(nullif(:patient,'') as uuid),:workflow,:form,cast(:data as jsonb),:status,:request) on conflict do nothing returning id::text",p,"Unable to save draft.");if(row.isEmpty())throw ApiException.conflict("An active draft already exists. Restore it instead of creating another draft.");return get(a,String.valueOf(row.get("id")));}
 public Map<String,Object> get(GovCarePrincipal a,String id){var row=sql.required("select id::text \"draftId\",patient_id::text \"patientId\",workflow_type \"workflowType\",form_type \"formType\",draft_data data,status,version,created_at \"createdAt\",updated_at \"updatedAt\" from workflow_drafts where id=cast(:id as uuid) and user_id=:user and (:network or hospital_id=:hospital) and status<>'ARCHIVED'",params(a,id,""),"Draft not found.");if("CKD_AI_ASSESSMENT".equals(row.get("workflowType"))&&row.get("patientId")!=null)access.requireClinical(a,sql.uuid(row.get("patientId"),"patientId"));return row;}
 public List<Map<String,Object>> list(GovCarePrincipal a,String workflow){if("CKD_AI_ASSESSMENT".equals(workflow))access.requireClinicalListAccess(a);return sql.list("select id::text \"draftId\",patient_id::text \"patientId\",workflow_type \"workflowType\",form_type \"formType\",status,version,updated_at \"updatedAt\" from workflow_drafts where user_id=:user and (:network or hospital_id=:hospital) and (:workflow='' or workflow_type=:workflow) and status<>'ARCHIVED' order by updated_at desc",params(a,null,workflow));}
 public Map<String,Object> archive(GovCarePrincipal a,String id,ActionRequest q){int n=sql.update("update workflow_drafts set status='ARCHIVED',archived_at=now(),updated_at=now() where id=cast(:id as uuid) and user_id=:user and (:network or hospital_id=:hospital) and status<>'SUBMITTED'",params(a,id,""));if(n==0)throw ApiException.conflict("Submitted or unavailable drafts cannot be archived.");return Map.of("status","ARCHIVED");}
 private Map<String,Object> params(GovCarePrincipal a,String id,String workflow){Map<String,Object> p=new HashMap<>();p.put("id",id);p.put("user",a.id());p.put("hospital",a.hospitalId());p.put("network",access.canAccessNetwork(a));p.put("workflow",workflow==null?"":workflow);return p;}
}
